def _register_font(name, candidates):
    """candidates: [(path, subfontIndex|None), ...]，第一个可用的生效（macOS/Linux 自适应）"""
    for path, idx in candidates:
        if os.path.exists(path):
            try:
                if idx is None:
                    pdfmetrics.registerFont(TTFont(name, path))
                else:
                    pdfmetrics.registerFont(TTFont(name, path, subfontIndex=idx))
                return True
            except Exception:
                continue
    print(f"Font warning: no usable font for {name}")
    return False

