def callout_box(text, bg='#e8f4f8', border=ACCENT):
    """Create a callout box with accent left border."""
    p = Paragraph(text, ParagraphStyle(name='CB', fontName='NotoSansSC', fontSize=10.5,
        textColor=TEXT_PRIMARY, alignment=TA_LEFT, leading=17, wordWrap='CJK',
        leftIndent=12, rightIndent=8, spaceBefore=6, spaceAfter=6))
    t = Table([[p]], colWidths=[AVAIL_W])
    t.setStyle(TableStyle([
        ('BACKGROUND', (0,0), (-1,-1), colors.HexColor(bg)),
        ('LINEBEFORE', (0,0), (0,-1), 3, border),
        ('TOPPADDING', (0,0), (-1,-1), 8),
        ('BOTTOMPADDING', (0,0), (-1,-1), 8),
        ('LEFTPADDING', (0,0), (-1,-1), 0),
        ('RIGHTPADDING', (0,0), (-1,-1), 8),
    ]))
    return t

def stat_card(num, label, sub=''):
    """Small stat card."""
    num_p = Paragraph(f'<font name="NotoSerifSC-Bold" size="22" color="#288fb1">{num}</font>',
        ParagraphStyle(name='SN', alignment=TA_CENTER, leading=26))
    label_p = Paragraph(f'<font name="NotoSansSC" size="9" color="#7b776f">{label}</font>',
        ParagraphStyle(name='SL', alignment=TA_CENTER, leading=12))
    elements = [num_p, label_p]
    if sub:
        sub_p = Paragraph(f'<font name="NotoSansSC" size="8" color="#7b776f">{sub}</font>',
            ParagraphStyle(name='SS', alignment=TA_CENTER, leading=10))
        elements.append(sub_p)
    t = Table([elements], colWidths=[AVAIL_W/4 - 6])
    t.setStyle(TableStyle([
        ('BACKGROUND', (0,0), (-1,-1), colors.HexColor('#f0f7fa')),
        ('TOPPADDING', (0,0), (-1,-1), 10),
        ('BOTTOMPADDING', (0,0), (-1,-1), 10),
        ('LEFTPADDING', (0,0), (-1,-1), 4),
        ('RIGHTPADDING', (0,0), (-1,-1), 4),
        ('LINEABOVE', (0,0), (-1,0), 2, ACCENT),
    ]))
    return t

def escape_xml(text):
    """Escape XML special characters for ReportLab Paragraph."""
    s = str(text)
    s = s.replace('&', '&amp;')
    s = s.replace('<', '&lt;')
    s = s.replace('>', '&gt;')
    return s

def make_table(headers, rows, col_ratios=None, highlight_rows=None):
    """Create a styled table."""
    if col_ratios is None:
        col_ratios = [1/len(headers)] * len(headers)
    col_widths = [r * AVAIL_W for r in col_ratios]

    data = [[Paragraph(h, th_style) for h in headers]]
    for row in rows:
        data.append([Paragraph(escape_xml(c), td_style if i > 0 else td_left) for i, c in enumerate(row)])

    t = Table(data, colWidths=col_widths, hAlign='CENTER')
    style_cmds = [
        ('BACKGROUND', (0,0), (-1,0), ACCENT),
        ('TEXTCOLOR', (0,0), (-1,0), colors.white),
        ('GRID', (0,0), (-1,-1), 0.5, colors.HexColor('#c0bdb6')),
        ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
        ('TOPPADDING', (0,0), (-1,-1), 6),
        ('BOTTOMPADDING', (0,0), (-1,-1), 6),
        ('LEFTPADDING', (0,0), (-1,-1), 8),
        ('RIGHTPADDING', (0,0), (-1,-1), 8),
    ]
    # Alternating row colors
    for i in range(1, len(data)):
        if i % 2 == 0:
            style_cmds.append(('BACKGROUND', (0,i), (-1,i), BG_SURFACE))
        else:
            style_cmds.append(('BACKGROUND', (0,i), (-1,i), colors.white))
    # Highlight specific rows
    if highlight_rows:
        for r in highlight_rows:
            style_cmds.append(('BACKGROUND', (0,r), (-1,r), colors.HexColor('#fff3cd')))
            style_cmds.append(('FONTNAME', (0,r), (-1,r), 'NotoSansSC-Bold'))

    t.setStyle(TableStyle(style_cmds))
    return t

